 SELECT 'MASTER_COUNT:'||e.key FROM approved_export a,LATERAL jsonb_each(a.value) e LEFT JOIN counts c ON c.name=e.key WHERE c.rows IS DISTINCT FROM jsonb_array_length(e.value)::bigint
 UNION ALL SELECT 'MASTER_ROW_MISSING_OR_CHANGED:'||e.name||':'||(e.record->>'id') FROM expected_master_rows e WHERE NOT EXISTS(SELECT 1 FROM actual_master_rows a WHERE a.name=e.name AND a.record=e.record)
 UNION ALL SELECT 'MASTER_ROW_UNAPPROVED:'||a.name||':'||(a.record->>'id') FROM actual_master_rows a WHERE NOT EXISTS(SELECT 1 FROM expected_master_rows e WHERE e.name=a.name AND e.record=a.record)
 UNION ALL SELECT 'MASTER_SEQUENCE_STATE:machine_family' WHERE EXISTS(SELECT 1 FROM sequence_state WHERE s->>'table'='machine_family' AND (last_value::bigint IS DISTINCT FROM 9 OR is_called::boolean IS DISTINCT FROM false))
 UNION ALL SELECT 'MASTER_SEQUENCE_STATE:machine_model' WHERE EXISTS(SELECT 1 FROM sequence_state WHERE s->>'table'='machine_model' AND (last_value::bigint IS DISTINCT FROM 52 OR is_called::boolean IS DISTINCT FROM false))
 UNION ALL SELECT 'MASTER_SEQUENCE_STATE:maintenance_template' WHERE EXISTS(SELECT 1 FROM sequence_state WHERE s->>'table'='maintenance_template' AND (last_value::bigint IS DISTINCT FROM 131 OR is_called::boolean IS DISTINCT FROM false))
 UNION ALL SELECT 'MASTER_SEQUENCE_STATE:template_section' WHERE EXISTS(SELECT 1 FROM sequence_state WHERE s->>'table'='template_section' AND (last_value::bigint IS DISTINCT FROM 406 OR is_called::boolean IS DISTINCT FROM false))
 UNION ALL SELECT 'MASTER_SEQUENCE_STATE:template_task' WHERE EXISTS(SELECT 1 FROM sequence_state WHERE s->>'table'='template_task' AND (last_value::bigint IS DISTINCT FROM 1251 OR is_called::boolean IS DISTINCT FROM false))
 UNION ALL SELECT 'MASTER_SEQUENCE_STATE:template_task_inspection' WHERE EXISTS(SELECT 1 FROM sequence_state WHERE s->>'table'='template_task_inspection' AND (last_value::bigint IS DISTINCT FROM 223 OR is_called::boolean IS DISTINCT FROM false))
 UNION ALL SELECT 'MASTER_SEQUENCE_STATE:plantilla_tecnicos' WHERE EXISTS(SELECT 1 FROM sequence_state WHERE s->>'table'='plantilla_tecnicos' AND (last_value::bigint IS DISTINCT FROM 131 OR is_called::boolean IS DISTINCT FROM false))
 UNION ALL SELECT 'TEST_MARKER:machine_family' WHERE EXISTS(SELECT 1 FROM public.machine_family a WHERE to_jsonb(a)::text ~* '(^|[^[:alnum:]])(TEST([_ -]LOCAL)?|FIXTURE)([^[:alnum:]]|$)')
 UNION ALL SELECT 'TEST_MARKER:machine_model' WHERE EXISTS(SELECT 1 FROM public.machine_model a WHERE to_jsonb(a)::text ~* '(^|[^[:alnum:]])(TEST([_ -]LOCAL)?|FIXTURE)([^[:alnum:]]|$)')
 UNION ALL SELECT 'TEST_MARKER:maintenance_template' WHERE EXISTS(SELECT 1 FROM public.maintenance_template a WHERE to_jsonb(a)::text ~* '(^|[^[:alnum:]])(TEST([_ -]LOCAL)?|FIXTURE)([^[:alnum:]]|$)')
 UNION ALL SELECT 'TEST_MARKER:template_section' WHERE EXISTS(SELECT 1 FROM public.template_section a WHERE to_jsonb(a)::text ~* '(^|[^[:alnum:]])(TEST([_ -]LOCAL)?|FIXTURE)([^[:alnum:]]|$)')
 UNION ALL SELECT 'TEST_MARKER:template_task' WHERE EXISTS(SELECT 1 FROM public.template_task a WHERE to_jsonb(a)::text ~* '(^|[^[:alnum:]])(TEST([_ -]LOCAL)?|FIXTURE)([^[:alnum:]]|$)')
 UNION ALL SELECT 'TEST_MARKER:template_task_inspection' WHERE EXISTS(SELECT 1 FROM public.template_task_inspection a WHERE to_jsonb(a)::text ~* '(^|[^[:alnum:]])(TEST([_ -]LOCAL)?|FIXTURE)([^[:alnum:]]|$)')
 UNION ALL SELECT 'TEST_MARKER:plantilla_tecnicos' WHERE EXISTS(SELECT 1 FROM public.plantilla_tecnicos a WHERE to_jsonb(a)::text ~* '(^|[^[:alnum:]])(TEST([_ -]LOCAL)?|FIXTURE)([^[:alnum:]]|$)')
 UNION ALL SELECT 'TEST_MARKER:logistica_authorized_users' WHERE EXISTS(SELECT 1 FROM public.logistica_authorized_users a WHERE to_jsonb(a)::text ~* '(^|[^[:alnum:]])(TEST([_ -]LOCAL)?|FIXTURE)([^[:alnum:]]|$)')
), functional_issues(reason) AS (
 SELECT reason FROM configuration_issues WHERE reason IN ('TEMPLATE_WITHOUT_SECTIONS','SECTION_WITHOUT_TASKS','SECTION_WITHOUT_INSPECTION_POINTS','INSPECTION_TYPE_MISSING','ASSEMBLY_INSPECTION_CONFIG_MISSING','ASSEMBLY_RELEASE_CODE_MISSING','TECHNICIAN_REQUIRED_FIELDS','DUPLICATE_TECHNICIAN_EMAIL','PRODUCTION_OPERATOR_MISSING','QUALITY_INSPECTOR_MISSING','AMBIGUOUS_INSPECTION') AND reason NOT IN ('TECHNICIAN_REQUIRED_FIELDS','DUPLICATE_TECHNICIAN_EMAIL')
), seed_issues(reason) AS (
 SELECT reason FROM schema_issues UNION ALL SELECT reason FROM master_data_issues
 UNION ALL SELECT reason FROM configuration_issues WHERE reason NOT IN ('TEMPLATE_WITHOUT_SECTIONS','SECTION_WITHOUT_TASKS','SECTION_WITHOUT_INSPECTION_POINTS','INSPECTION_TYPE_MISSING','ASSEMBLY_INSPECTION_CONFIG_MISSING','ASSEMBLY_RELEASE_CODE_MISSING','TECHNICIAN_REQUIRED_FIELDS','DUPLICATE_TECHNICIAN_EMAIL','PRODUCTION_OPERATOR_MISSING','QUALITY_INSPECTOR_MISSING','AMBIGUOUS_INSPECTION')
), inherited_warning_policy(reason,classification,affected,impact) AS (
 VALUES ('ASSEMBLY_INSPECTION_CONFIG_MISSING','BLOQUEADOR_FLUJO_ESPECIFICO','[{"template_id":19,"model_id":1},{"template_id":30,"model_id":23},{"template_id":31,"model_id":23},{"template_id":32,"model_id":10},{"template_id":33,"model_id":24},{"template_id":34,"model_id":25},{"template_id":37,"model_id":16},{"template_id":38,"model_id":27},{"template_id":39,"model_id":28},{"template_id":40,"model_id":28},{"template_id":41,"model_id":14},{"template_id":42,"model_id":8},{"template_id":43,"model_id":29},{"template_id":44,"model_id":30},{"template_id":45,"model_id":31},{"template_id":48,"model_id":33},{"template_id":49,"model_id":27},{"template_id":50,"model_id":34},{"template_id":55,"model_id":35},{"template_id":56,"model_id":36},{"template_id":57,"model_id":17},{"template_id":61,"model_id":15},{"template_id":65,"model_id":27},{"template_id":69,"model_id":36},{"template_id":70,"model_id":36},{"template_id":71,"model_id":37},{"template_id":72,"model_id":38},{"template_id":74,"model_id":39},{"template_id":75,"model_id":40},{"template_id":77,"model_id":36},{"template_id":105,"model_id":38},{"template_id":109,"model_id":42},{"template_id":111,"model_id":2},{"template_id":112,"model_id":43},{"template_id":116,"model_id":44},{"template_id":120,"model_id":48},{"template_id":125,"model_id":49},{"template_id":128,"model_id":50},{"template_id":130,"model_id":51}]'::jsonb,'Order creation and existing activities continue; POST /api10/quality/inspection/request returns 404 for these models.'),
 ('SECTION_WITHOUT_TASKS','ADVERTENCIA_HEREDADA','[{"section_id":155,"template_id":50},{"section_id":249,"template_id":61},{"section_id":250,"template_id":61},{"section_id":263,"template_id":69},{"section_id":264,"template_id":69}]'::jsonb,'Order creation succeeds; empty sections produce no activities or checklist group. Templates 61/69 have no activities at all; their checklist reset returns 404.'),
 ('ASSEMBLY_RELEASE_CODE_MISSING','BLOQUEADOR_FLUJO_ESPECIFICO','[{"template_id":30,"missing":["LIB001","LIB002"]},{"template_id":31,"missing":["LIB001","LIB002"]},{"template_id":32,"missing":["LIB001","LIB002"]},{"template_id":34,"missing":["LIB002"]},{"template_id":38,"missing":["LIB002"]},{"template_id":49,"missing":["LIB002"]},{"template_id":55,"missing":["LIB001","LIB002"]},{"template_id":61,"missing":["LIB001","LIB002"]},{"template_id":69,"missing":["LIB001","LIB002"]}]'::jsonb,'Order creation and existing activities continue; quality release returns 404 and inspection completion 409 if the required release task is absent.')
), blocking_issues(reason) AS (
 SELECT reason FROM seed_issues
 UNION ALL SELECT reason FROM functional_issues WHERE reason NOT IN ('ASSEMBLY_INSPECTION_CONFIG_MISSING','SECTION_WITHOUT_TASKS','ASSEMBLY_RELEASE_CODE_MISSING')
), authorization AS (
 SELECT NOT EXISTS(SELECT 1 FROM public.logistica_authorized_users WHERE firebase_project='logistica-ar' AND is_active=true AND btrim(firebase_uid)<>'') AS pending
), report AS (
 SELECT 0 AS position,'CALIDAD_SCHEMA_VALIDO'::text AS "CHECK",CASE WHEN EXISTS(SELECT 1 FROM schema_issues) THEN 'NO' ELSE 'SI' END AS "ESTADO",'{}'::jsonb AS "DETALLE"
 UNION ALL SELECT 1,'INCIDENCIA_DATOS','ERROR',jsonb_build_object('reason',reason) FROM seed_issues
 UNION ALL SELECT 2,'LIMITACION_FUNCIONAL','ERROR',jsonb_build_object('reason',reason) FROM functional_issues WHERE reason NOT IN ('ASSEMBLY_INSPECTION_CONFIG_MISSING','SECTION_WITHOUT_TASKS','ASSEMBLY_RELEASE_CODE_MISSING')
 UNION ALL SELECT 2,'ADVERTENCIA_HEREDADA','WARNING',jsonb_build_object('reason',p.reason,'classification',p.classification,'affected_count',jsonb_array_length(p.affected),'affected',p.affected,'impact',p.impact) FROM configuration_issues c JOIN inherited_warning_policy p ON p.reason=c.reason
 UNION ALL SELECT 2,'OBSERVACION_CONFIGURACION','WARNING',jsonb_build_object('reason',reason) FROM configuration_issues WHERE reason IN ('TECHNICIAN_REQUIRED_FIELDS','DUPLICATE_TECHNICIAN_EMAIL')
 UNION ALL SELECT 3,'CONFIGURACION_CONTEO','INFO',jsonb_build_object('table',e.key,'expected',jsonb_array_length(e.value),'actual',c.rows) FROM approved_export a,LATERAL jsonb_each(a.value) e LEFT JOIN counts c ON c.name=e.key
 UNION ALL SELECT 4,'CALIDAD_SEED_DATOS_VALIDOS',CASE WHEN EXISTS(SELECT 1 FROM seed_issues) THEN 'NO' ELSE 'SI' END,jsonb_build_object('approved_rows',1139,'source_sha256','47f5dddeb498f7b50ee61c7148f10bfa7635aaf773b12495134ffe8147349bd0')
 UNION ALL SELECT 5,'LOGISTICA_AUTH_PENDIENTE',CASE WHEN pending THEN 'SI' ELSE 'NO' END,jsonb_build_object('action',CASE WHEN pending THEN 'ALTA_MANUAL_REQUERIDA' ELSE 'AUTORIZACION_PRESENTE' END,'scope','LOGISTICA','classification','BLOQUEADOR_FLUJO_ESPECIFICO') FROM authorization
 UNION ALL SELECT 6,'CALIDAD_SEED_OPERATIVO_VALIDO',CASE WHEN EXISTS(SELECT 1 FROM blocking_issues) THEN 'NO' ELSE 'SI' END,jsonb_build_object('source_status','EXPORT_CONFIG_PROD_RECIBIDO','transactional_rows',(SELECT sum(rows) FROM counts WHERE name NOT IN ('logistica_schema_migrations','machine_family','machine_model','maintenance_template','template_section','template_task','template_task_inspection','plantilla_tecnicos','logistica_authorized_users')))
 UNION ALL SELECT 7,'BASELINE_APTO_PARA_DEPLOY',CASE WHEN EXISTS(SELECT 1 FROM blocking_issues) THEN 'NO' ELSE 'SI' END,jsonb_build_object('logistics_authorization','SEPARATE_MANUAL_REQUIREMENT')
) SELECT "CHECK","ESTADO","DETALLE" FROM report ORDER BY position,"CHECK","DETALLE"::text;
